import {projectLink} from './config.js';
import {configurePublisher,exportProject} from './project-store.js';
import {api,asset,putAsset,autoLink,parseCSV,escapeHTML as esc} from './common.js';
const $=s=>document.querySelector(s);let projects=[],current=null,components=[],selected=new Set(),filter='all',folder='',dirty=false,busy=false,toastTimer;
function toast(s,error=false){$('#toast').textContent=s;$('#toast').className=error?'error':'';$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,error?12000:6000);}
async function action(fn){if(busy)return;busy=true;document.body.style.cursor='progress';try{await fn();}catch(e){toast(e.message,true);}finally{busy=false;document.body.style.cursor='';}}
const link=projectLink;
const viewMessage=d=>$('#modelView').contentWindow?.postMessage(d,location.origin);
function mark(){dirty=true;}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
function render(){let rows=projects.filter(p=>(filter==='all'?p.status!=='archived':p.status===filter)&&(!folder||p.folder===folder)&&p.name.toLowerCase().includes($('#search').value.toLowerCase()));$('#total').textContent=projects.filter(p=>p.status!=='archived').length+1;
const law=filter==='all'&&!folder&&'law office'.includes($('#search').value.toLowerCase())?`<article class="card"><div class="cardimage"><img src="./examples/law-office.jpg" alt="Law Office model"><span class="badge">EXISTING LIVE APP</span></div><div class="cardbody"><h3>Law Office</h3><p>Original model · 20 activities</p><div class="cardfooter"><span>Preserved · independent app</span><a href="https://mforoughi.github.io/AR-lab/?sheet=poster" target="_blank" rel="noopener">Open ↗</a></div></div></article>`:'';
$('#cards').innerHTML=law+rows.map(p=>`<article class="card"><div class="cardimage"><img src="${asset(p.id,'thumbnail')}" alt="${esc(p.name)} preview" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="placeholder" hidden>▱</span><span class="badge">${esc(p.status.toUpperCase())}</span></div><div class="cardbody"><h3>${esc(p.name)}</h3><p>${esc(p.folder||'Unsorted')} · ${p.metadata.tasks?.length||0} activities</p><div class="cardfooter"><span>${new Date(p.updated).toLocaleDateString()}</span><button data-open="${p.id}">Manage ↗</button></div></div></article>`).join('')+`<button class="card newcard" id="addCard"><div><span style="font-size:30px">＋</span><strong>Add a new perspective</strong><p>Upload a model to get started</p></div></button>`;
$('#addCard').onclick=()=>$('#createDialog').showModal();document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>action(()=>openProject(b.dataset.open)));$('#folders').replaceChildren();for(const f of [...new Set(projects.map(p=>p.folder).filter(Boolean))]){let b=document.createElement('button');b.className='nav';b.textContent='▱  '+f;b.onclick=()=>{folder=f;filter='all';render();};$('#folders').append(b);}document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===filter&&!folder));}
async function refresh(){projects=await api('projects');render();}
async function openProject(id){if(dirty&&!confirm('Leave without saving your changes?'))return;current=await api('projects/'+id);dirty=false;selected.clear();components=[];$('#gallery').hidden=true;$('#editor').hidden=false;$('#projectName').value=current.name;$('#projectFolder').value=current.folder;$('#projectDescription').value=current.metadata.description||'';const a=current.metadata.alignment;$('#width').value=a.width;$('#offsetX').value=a.x;$('#offsetY').value=a.y;$('#rotation').value=a.rotation;updateEditor();$('#modelView').src='./viewer.html?id='+id+'&edit=1';QRCode.toCanvas($('#qr'),link(id),{width:160,margin:2});$('#projectLink').href=link(id);$('#draftLink').href='./viewer.html?id='+id+'&edit=1';}
function updateEditor(){$('#editTitle').textContent=current.name;$('#editStatus').textContent=current.status.toUpperCase()+' PROJECT';$('#publish').textContent=current.status==='published'?'Edit published project':'Publish to GitHub';$('#archive').textContent=current.status==='archived'?'Restore to draft':'Archive project';$('#publishNote').textContent=current.status==='published'?'Published to GitHub. Deployment may take a few minutes. Your QR opens the public AR viewer.':current.hasPublished?'Draft changes are saved in this browser. The QR still opens the last published version until you publish again.':'Draft saved in this browser. Publish to GitHub before sharing or scanning its QR on another device.';$('#assetList').innerHTML=current.assets.map(a=>`<div class="assetrow"><span>${esc(a.kind)}</span><a href="${asset(current.id,a.kind)}" download="${esc(a.filename)}">${(a.size/1024/1024).toFixed(2)} MB ↓</a></div>`).join('');for(const id of ['modelFile','planFile','scheduleFile','generateSheet'])$('#'+id).disabled=current.status==='published';alignment();renderTasks();renderComponents();}
function metadata(){return {...current.metadata,description:$('#projectDescription').value,alignment:{width:+$('#width').value,x:+$('#offsetX').value,y:+$('#offsetY').value,rotation:+$('#rotation').value}};}
async function save(){await api('projects/'+current.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('#projectName').value,folder:$('#projectFolder').value,metadata:metadata()})});current=await api('projects/'+current.id);dirty=false;updateEditor();toast('Draft saved in this browser.');}
async function upload(kind,file){current=await putAsset(current.id,kind,file);}
function renderTasks(){const tasks=current.metadata.tasks||[];$('#taskList').innerHTML=tasks.map(t=>`<div class="taskrow"><b>${esc(t.id)}</b><span>${esc(t.name)}</span><span>Day ${t.start}–${t.start+t.duration}</span></div>`).join('');$('#taskSelect').innerHTML='<option value="">Choose a task</option>'+tasks.map(t=>`<option value="${esc(t.id)}">${esc(t.id+' · '+t.name)}</option>`).join('');}
function renderComponents(){const q=$('#componentSearch').value.toLowerCase(),rows=components.filter(c=>c.name.toLowerCase().includes(q));$('#components').innerHTML=rows.map(c=>`<label class="componentrow"><input type="checkbox" data-mesh="${c.id}" ${selected.has(c.id)?'checked':''}><span>${esc(c.name)}</span><small>${esc(current.metadata.mappings[c.id]||'Unlinked')}</small></label>`).join('');$('#mappingSummary').textContent=components.length+' components · '+Object.keys(current.metadata.mappings).length+' linked · '+selected.size+' selected';document.querySelectorAll('[data-mesh]').forEach(c=>c.onchange=()=>{c.checked?selected.add(c.dataset.mesh):selected.delete(c.dataset.mesh);viewMessage({type:'highlight',ids:[...selected]});$('#mappingSummary').textContent=components.length+' components · '+Object.keys(current.metadata.mappings).length+' linked · '+selected.size+' selected';});}
function alignment(){if(!current)return;$('#widthOut').textContent=Math.round(+$('#width').value*100)+'%';$('#rotationOut').textContent=$('#rotation').value+'°';viewMessage({type:'alignment',alignment:metadata().alignment});}
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==$('#modelView').contentWindow||!current||e.data.projectId!==current.id)return;if(e.data.type==='components'){if(e.data.metadata?.stadiumScheduleLinked&&JSON.stringify(e.data.metadata.tasks)===JSON.stringify(current.metadata.tasks)&&!current.metadata.stadiumScheduleLinked&&!Object.keys(current.metadata.mappings||{}).length){current.metadata.mappings=e.data.metadata.mappings;current.metadata.stadiumScheduleLinked=true;toast('339 stadium components linked to the schedule.');}components=e.data.components;$('#modelSummary').textContent=components.length+' components · drag to orbit · scroll to zoom';renderComponents();alignment();}if(e.data.type==='select'){selected.has(e.data.id)?selected.delete(e.data.id):selected.add(e.data.id);renderComponents();viewMessage({type:'highlight',ids:[...selected]});}if(e.data.type==='thumbnail'&&current.status!=='published'){fetch(e.data.data).then(r=>r.blob()).then(b=>upload('thumbnail',b)).catch(()=>{});}});
async function imageBlob(url){const r=await fetch(url);if(!r.ok)throw new Error('Image could not load.');return createImageBitmap(await r.blob());}
async function generateSheet(){await save();if(!current.assets.some(a=>a.kind==='plan'))throw new Error('Upload a floor plan or tracking image first.');const img=await imageBlob(asset(current.id,'plan'));const c=document.createElement('canvas');c.width=960;c.height=1280;const g=c.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,960,1280);g.fillStyle='#183c35';g.fillRect(0,0,960,166);g.fillStyle='#d6b56c';g.font='bold 20px sans-serif';g.fillText('CONSTRUCTION AR LAB',42,45);g.fillStyle='white';g.font='bold 38px sans-serif';g.fillText(current.name,42,105,870);g.font='17px sans-serif';g.fillText('MODEL / DRAWING / TIME',42,143);const fit=Math.min(840/img.width,820/img.height),w=img.width*fit,h=img.height*fit;g.drawImage(img,(960-w)/2,200+(820-h)/2,w,h);g.strokeStyle='#183c35';g.lineWidth=4;g.strokeRect(40,190,880,840);g.fillStyle='#183c35';g.fillRect(0,1080,960,200);const qr=document.createElement('canvas');await QRCode.toCanvas(qr,link(current.id),{width:170,margin:3});g.drawImage(qr,750,1095);g.fillStyle='#fff';g.font='bold 23px sans-serif';g.fillText('SCAN TO EXPLORE',42,1130);g.font='18px sans-serif';g.fillText('Allow camera access. Keep the whole sheet in view.',42,1170);g.fillText('Dr. Mohsen Foroughi',42,1210);g.font='14px sans-serif';g.fillText('School of Construction and Design · USM',42,1240);const blob=await new Promise(r=>c.toBlob(r,'image/png'));const target=document.createElement('canvas');target.width=480;target.height=640;const t=target.getContext('2d');t.drawImage(c,0,0,480,640);const px=t.getImageData(0,0,480,640);for(let i=0;i<px.data.length;i+=4){const l=Math.round(.299*px.data[i]+.587*px.data[i+1]+.114*px.data[i+2]);px.data[i]=px.data[i+1]=px.data[i+2]=l;}t.putImageData(px,0,0);await upload('sheet',blob);await upload('target',await new Promise(r=>target.toBlob(r,'image/png')));current=await api('projects/'+current.id);updateEditor();$('#modelView').src='./viewer.html?id='+current.id+'&edit=1&calibrate=1';toast('Tracking sheet ready. Align the model before publishing.');}
$('#newProject').onclick=()=>$('#createDialog').showModal();$('#cancelCreate').onclick=()=>$('#createDialog').close();$('#createForm').onsubmit=e=>{e.preventDefault();action(async()=>{const p=await api('projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('#newName').value,folder:$('#newFolder').value})});$('#createDialog').close();$('#createForm').reset();await openProject(p.id);});};
$('#back').onclick=()=>action(async()=>{if(dirty&&!confirm('Leave without saving?'))return;dirty=false;$('#modelView').src='about:blank';$('#editor').hidden=true;$('#gallery').hidden=false;await refresh();});
$('#save').onclick=()=>action(save);$('#publish').onclick=()=>action(async()=>{
 if(current.status==='published'){
  current=await api('projects/'+current.id,{method:'PATCH',body:JSON.stringify({status:'draft'})});updateEditor();toast('Draft opened. The published QR continues to work.');return;
 }
 await save();
 current=await api('projects/'+current.id,{method:'PATCH',body:JSON.stringify({status:'published'})});
 updateEditor();toast('Sent to GitHub. Allow a few minutes for deployment, then scan the new sheet.');
});
$('#archive').onclick=()=>action(async()=>{const status=current.status==='archived'?'draft':'archived';if(status==='archived'&&!confirm('Archive this browser draft? Its published version and QR link will keep working.'))return;await api('projects/'+current.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})});current=await api('projects/'+current.id);updateEditor();});
for(const [id,kind]of [['modelFile','model'],['planFile','plan']])$('#'+id).onchange=e=>action(async()=>{const f=e.target.files[0];if(!f)return;await save();toast('Preparing '+f.name+'…');await upload(kind,f);await openProject(current.id);toast('File saved in this browser. Publish when ready.');e.target.value='';});
$('#scheduleFile').onchange=e=>action(async()=>{const f=e.target.files[0];if(!f)return;const tasks=parseCSV(await f.text());const old=current.metadata;current.metadata={...old,tasks,mappings:{},stadiumScheduleLinked:false};try{await save();await upload('schedule',f);current=await autoLink(current.id);}catch(err){current.metadata=old;throw err;}renderTasks();renderComponents();viewMessage({type:'schedule',metadata:metadata()});$('#modelView').src='./viewer.html?id='+current.id+'&edit=1';toast('Schedule imported. Checking model links…');e.target.value='';});
$('#clearSchedule').onclick=()=>{if(!confirm('Clear all schedule tasks and component links?'))return;current.metadata.tasks=[];current.metadata.mappings={};mark();renderTasks();renderComponents();viewMessage({type:'schedule',metadata:metadata()});};
$('#assign').onclick=()=>{const task=$('#taskSelect').value;if(!task||!selected.size)return toast('Select components and choose a task.',true);for(const id of selected)current.metadata.mappings[id]=task;mark();renderComponents();viewMessage({type:'schedule',metadata:metadata()});};$('#unlink').onclick=()=>{for(const id of selected)delete current.metadata.mappings[id];mark();renderComponents();viewMessage({type:'schedule',metadata:metadata()});};$('#componentSearch').oninput=renderComponents;$('#selectVisible').onclick=()=>{const q=$('#componentSearch').value.toLowerCase();components.filter(c=>c.name.toLowerCase().includes(q)).forEach(c=>selected.add(c.id));renderComponents();viewMessage({type:'highlight',ids:[...selected]});};$('#clearSelection').onclick=()=>{selected.clear();renderComponents();viewMessage({type:'highlight',ids:[]});};
for(const id of ['width','offsetX','offsetY','rotation'])$('#'+id).oninput=()=>{mark();alignment();};for(const id of ['projectName','projectFolder','projectDescription'])$('#'+id).oninput=mark;
$('#resetAlignment').onclick=()=>{$('#width').value=.7;$('#offsetX').value=0;$('#offsetY').value=0;$('#rotation').value=0;mark();alignment();};$('#view3d').onclick=()=>viewMessage({type:'view',mode:'3d'});$('#viewPlan').onclick=()=>viewMessage({type:'view',mode:'plan'});$('#generateSheet').onclick=()=>action(generateSheet);
$('#printSheet').onclick=()=>{if(!current.assets.some(a=>a.kind==='sheet'))return toast('Generate a tracking sheet first.',true);window.open('./print.html?id='+current.id+'&edit=1','_blank');};$('#downloadQR').onclick=()=>{const a=document.createElement('a');a.href=$('#qr').toDataURL();a.download='project-qr.png';a.click();};$('#copyLink').onclick=()=>action(async()=>{await navigator.clipboard.writeText(link(current.id));toast('Project link copied.');});
$('#search').oninput=render;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;folder='';render();});$('#allProjects').onclick=()=>{filter='all';folder='';render();};$('#publishedOnly').onclick=()=>{filter='published';folder='';render();};$('#draftsOnly').onclick=()=>{filter='draft';folder='';render();};
$('#sampleProject').onclick=()=>action(async()=>{const p=await api('projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:'Soccer Stadium',folder:'Concept models'})});await openProject(p.id);await upload('model',new File([await (await fetch('./examples/stadium.glb')).blob()],'soccer-stadium.glb'));await upload('plan',new File([await (await fetch('./examples/stadium-plan.png')).blob()],'stadium-plan.png'));await upload('thumbnail',await(await fetch('./examples/stadium-preview.png')).blob());const csv=await(await fetch('./examples/stadium-schedule.csv')).text();current.metadata.tasks=parseCSV(csv);await save();await upload('schedule',new File([csv],'stadium-schedule.csv',{type:'text/csv'}));current=await autoLink(p.id);await openProject(p.id);toast('Stadium and eight linked tasks imported. Generate its sheet to continue.');});
render();action(refresh);

$('#backup').onclick=()=>action(async()=>{await save();const blob=await exportProject(current.id);const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=current.name.replace(/[^a-zA-Z0-9_-]/g,'_')+'-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Project backup downloaded.');});
configurePublisher(job=>new Promise((resolve,reject)=>{
 const dialog=$('#publishDialog'),form=$('#publishForm'),button=$('#confirmPublish'),cancel=$('#cancelPublish'),input=$('#githubToken');
 $('#publishProgress').textContent='';$('#githubCommit').hidden=true;button.disabled=false;cancel.disabled=false;input.value='';dialog.showModal();
 const cleanup=()=>{input.value='';form.onsubmit=null;cancel.onclick=null;dialog.oncancel=null;dialog.close();};
 const abort=()=>{cleanup();reject(new Error('Publishing cancelled. Your draft is saved.'));};
 cancel.onclick=abort;dialog.oncancel=e=>{e.preventDefault();if(!button.disabled)abort();};
 form.onsubmit=async e=>{
  e.preventDefault();button.disabled=true;cancel.disabled=true;
  let token=input.value.trim();input.value='';
  try{const result=await job(token,text=>$('#publishProgress').textContent=text);$('#githubCommit').href=result.url;$('#githubCommit').hidden=false;cleanup();resolve(result);}
  catch(error){$('#publishProgress').textContent=error.message;button.disabled=false;cancel.disabled=false;}
  finally{token='';}
 };
}));
document.addEventListener('manager-status',e=>toast(e.detail,true));
